// Summons at their owner's training (docs/spec/summons.md 召唤-1…召唤-4): a summon's training data, generated by
// @aue/data into data/tokens/<id>.json, assembled at its owner's build — attributes, talents and skill (召唤-2), its
// limits (召唤-3) and its card (召唤-4) — as @aue/sim's operator record. The PRTS fields of each summon are in
// data/summons.json.
import index from '../data/tokens/index.json' with { type: 'json' };
import pages from '../data/summons.json' with { type: 'json' };
import { moduleAt, recordAt, statsAt } from './operators.js';
import { talentsAt, unlockedAt } from './talents.js';
import { grantAt as grantText, lifeAt, skillEndAt } from './summontext.js';

/** @typedef {import('./operators.js').Training} Training @typedef {import('./operators.js').Build} Build */
/** @typedef {import('./operators.js').Module['levels'][number]} ModuleLevel @typedef {import('./operators.js').ModulePart} ModulePart */
/** @typedef {Record<string, number>} Stats */
/**
 * A summon's PRTS fields (召唤-4, 召唤-5): 部署占用数, 再部署策略, 实体类型 装置, 部署位置 when it differs, whether it
 * stays when its owner leaves, and the page revision.
 * @typedef {{ page: string, oldid: number, occupy: number, respawn: 'default' | 'unique' | 'queue', device: boolean, position?: string,
 *   stays?: boolean, occupyUnknown?: boolean, effects?: string[], immune?: string[], unattacked?: boolean, ownerRange?: boolean, tactical?: boolean }} SummonPage
 */

/** Every summon there is training data for, by id: name and position. */
export const TOKENS = /** @type {Readonly<Record<string, { name: string, position: string }>>} */ (index.tokens);
/** Each summon's PRTS fields, by id. */
export const SUMMON_PAGES = /** @type {Readonly<Record<string, SummonPage>>} */ (pages.summons);

/** A summon's training data (召唤-1), loaded on first use. @param {string} id @returns {Promise<Training>} */
export async function loadToken(id) {
  if (!Object.hasOwn(TOKENS, id)) throw new RangeError(`no summon ${id}`);
  return (await import(`../data/tokens/${id}.json`, { with: { type: 'json' } })).default;
}

/**
 * A summon's build from its owner's (召唤-2): the owner's elite phase (its last when it has fewer), the owner's level
 * within the phase's, the owner's potential for its talents, no trust; the skill slot of the owner's skill, when the
 * summon has one there, at the owner's skill level.
 * @param {Training} token @param {Build} b @returns {Build}
 */
export function tokenBuild(token, b) {
  const elite = Math.min(b.elite, token.phases.length - 1), slot = b.skill >= 0 ? token.skills[b.skill] : null;
  return {
    elite, level: Math.min(Math.max(1, b.level), token.phases[elite].maxLevel), potential: b.potential, trust: 0,
    skill: slot && slot.phase <= elite ? b.skill : -1, skillLevel: b.skillLevel,
  };
}

/**
 * What the owner's module level gives a summon (召唤-2): the attributes for it, and the parts for summons as its own
 * talent upgrades; null when the owner has no module on.
 * @param {Training} owner @param {Build} b @param {string} id @returns {ModuleLevel | null}
 */
export function tokenModule(owner, b, id) {
  const m = moduleAt(owner, b);
  return m ? { level: m.level, stats: m.tokens[id] ?? {}, tokens: {}, parts: m.parts.filter((p) => p.token).map((p) => ({ ...p, token: false })) } : null;
}

/**
 * Each talent's blackboard at a build (干员-6): its last candidate unlocked, or a module part's upgrade of it (干员-7)
 * — the parts valid in every mode and map, `token` the parts for summons or the others; {} for a talent with none.
 * @param {Training} t @param {Build} b @param {ModuleLevel | null} mod @param {boolean} token @returns {Stats[]}
 */
function talentBoards(t, b, mod, token) {
  const out = talentsAt(t, b).map((c) => c?.bb ?? {});
  for (const p of /** @type {ModulePart[]} */ (mod?.parts ?? [])) {
    if (!p.target.startsWith('TALENT') || p.token !== token || p.gameTag || p.mapTag) continue;
    for (const c of p.talents) if (c.index >= 0 && unlockedAt(c, b)) out[c.index] = c.bb;
  }
  return out;
}

/**
 * A summon's limits (召唤-3): on the field, maxDeployCount and its talents' and module's max_deploy_count; held, the
 * larger of that and its stack (maxDeckStackCnt and max_deck_stack_cnt).
 * @param {Training} token @param {Build} tb @param {ModuleLevel | null} mod
 */
export function limitsAt(token, tb, mod) {
  const s = statsAt(token, tb, mod), boards = talentBoards(token, tb, mod, false);
  /** @param {string} k */
  const sum = (k) => boards.reduce((a, bb) => a + (bb[k] ?? 0), 0);
  const deployLimit = (s.maxDeployCount ?? 1) + sum('max_deploy_count');
  return { deployLimit, holdLimit: Math.max(deployLimit, (s.maxDeckStackCnt ?? 0) + sum('max_deck_stack_cnt')) };
}

/**
 * How many of a summon its owner's deployment adds to the card (召唤-4): the `cnt` of the owner's talent that names it,
 * or — when every skill of the owner summons one — talent 0's `cnt` for the one its skill summons; 0 for none.
 * @param {Training} owner @param {Build} b @param {string} id
 */
export function supplyAt(owner, b, id) {
  const boards = talentBoards(owner, b, moduleAt(owner, b), false);
  const bySkill = owner.skills.length > 0 && owner.skills.every((s) => s?.token), chosen = b.skill >= 0 ? owner.skills[b.skill]?.token : undefined;
  for (const [i, bb] of boards.entries()) {
    const named = (owner.talents[i] ?? []).find((c) => c.token)?.token ?? null;
    if (Number.isFinite(bb.cnt) && (named === id || (named === null && i === 0 && bySkill && chosen === id))) return bb.cnt;
  }
  return 0;
}

/** The engine's flags of the 异常效果 a summon holds (召唤-7). @type {Readonly<Record<string, string[]>>} */
const HELD = Object.freeze({
  禁疗: ['healFree'], 无敌: ['invincible'], 孤立: ['isolated', 'noAllyHeal'], 不可阻挡: ['unblockable'], 静默: ['mute'], 不死: ['undying'], 无法撤退: ['noRetreat'],
});
/** The flags of the 异常效果 a summon may be immune to (召唤-7, 状态-7). @type {Readonly<Record<string, string>>} */
const IMMUNE = Object.freeze({ 晕眩: 'stun', 冻结: 'freeze', 沉睡: 'sleep', 浮空: 'levitate', 沉默: 'silence', 恐惧: 'fear', 麻痹: 'palsy', 麻痹震颤: 'palsyShake' });

/**
 * What a summon's page says it holds (召唤-7): the flags it is deployed with — untargetable when it is not attacked or is
 * a device, those of the effects it holds — and the flags it is immune to; the effects the engine has none for are left out.
 * @param {SummonPage | null} page
 */
export function effectsOf(page) {
  const held = (page?.effects ?? []).flatMap((e) => HELD[e] ?? []), untargetable = page?.unattacked === true || page?.device === true;
  return { flags: Object.fromEntries([...(untargetable ? ['untargetable'] : []), ...held].map((f) => [f, true])), immune: (page?.immune ?? []).map((e) => IMMUNE[e]).filter(Boolean) };
}

/**
 * A record with a summon's effects (召唤-7): the flags on its trait, the immunities with its own.
 * @param {import('@aue/sim').OperatorDef} rec @param {SummonPage | null} page @returns {import('@aue/sim').OperatorDef}
 */
function withEffects(rec, page) {
  const { flags, immune } = effectsOf(page);
  return {
    ...rec, ...(Object.keys(flags).length ? { trait: { ...rec.trait, flags: { ...rec.trait?.flags, ...flags } } } : {}),
    ...(immune.length ? { immune: [...(rec.immune ?? []), ...immune] } : {}),
  };
}

/**
 * The copies of a summon its owner's skill gives and when (召唤-8, summontext.js), or null.
 * @param {Training} owner @param {Build} b @param {string} id @param {string} name
 */
export const grantAt = (owner, b, id, name) => grantText(owner, b, id, name, TOKENS);

/**
 * A summon at its owner's training as @aue/sim reads it (召唤-2…召唤-4, 召唤-7…召唤-11): its record, with its PRTS
 * position and effects, and `summon` — its limits, what the owner's deployment adds to its card, what its skill gives and
 * when, how long it stays and what its owner's skill's end does to it, 部署占用数, 再部署策略, whether it stays when the
 * owner leaves, a tactical point's forms.
 * @param {Training} token @param {string} id @param {Training} owner @param {Build} b @returns {import('@aue/sim').OperatorDef}
 */
export function tokenAt(token, id, owner, b) {
  const tb = tokenBuild(token, b), mod = tokenModule(owner, b, id), page = Object.hasOwn(SUMMON_PAGES, id) ? SUMMON_PAGES[id] : null, rec = recordAt(token, tb, mod);
  return {
    ...withEffects(rec, page), ...(page?.position ? { position: /** @type {'MELEE' | 'RANGED'} */ (page.position) } : {}),
    summon: { ...limitsAt(token, tb, mod), ...cardOf(token, id, owner, b), ...leavingOf(token, id, owner, b), occupy: page?.occupy ?? 0,
      respawn: page?.respawn ?? 'default', ...(page?.stays ? { stays: true } : {}), ...(page?.ownerRange ? { ownerRange: true } : {}),
      ...(page?.tactical ? { tactical: tacticalAt(token, tb, rec.blockCnt) } : {}) },
  };
}

/**
 * A tactical point's forms (召唤-11): the seconds of its point form — the `interval` of its talents — and the block bonus
 * of its summon form — their `block_cnt`, else 1 when its own 阻挡数 is 0.
 * @param {Training} token @param {Build} tb its build (召唤-2) @param {number} blockCnt its 阻挡数 at that build
 * @returns {{ every: number, block: number }}
 */
export function tacticalAt(token, tb, blockCnt) {
  const bbs = talentsAt(token, tb).flatMap((c) => (c ? [c.bb] : []));
  const every = bbs.find((bb) => bb.interval !== undefined)?.interval ?? 0;
  return { every, block: bbs.find((bb) => bb.block_cnt !== undefined)?.block_cnt ?? (blockCnt === 0 ? 1 : 0) };
}

/**
 * When a summon leaves by itself (召唤-9, 召唤-10): the seconds it stays, and what the end of its owner's skill does to it.
 * @param {Training} token @param {string} id @param {Training} owner @param {Build} b
 * @returns {{ life?: number, skillEnd?: { recover: boolean, below?: number } }}
 */
function leavingOf(token, id, owner, b) {
  const life = lifeAt(token, id, owner, b, { known: TOKENS, tactical: SUMMON_PAGES[id]?.tactical === true, tb: tokenBuild(token, b) });
  const end = skillEndAt(owner, b, id, token.name, TOKENS);
  return { ...(life > 0 ? { life } : {}), ...(end ? { skillEnd: end } : {}) };
}

/**
 * What fills a summon's card (召唤-4, 召唤-8): its owner's deployment — the talent's count and what the skill gives then
 * — and what the skill gives at its start or end.
 * @param {Training} token @param {string} id @param {Training} owner @param {Build} b
 * @returns {{ supply: number, grant?: { n: number, at: 'start' | 'end' } }}
 */
function cardOf(token, id, owner, b) {
  const g = grantAt(owner, b, id, token.name), supply = supplyAt(owner, b, id);
  if (!g || g.n <= 0) return { supply };
  return g.at === 'deploy' ? { supply: supply + g.n } : { supply, grant: { n: g.n, at: g.at } };
}
